    #[test]
    fn reopened_interface_and_class_auto_accessor_merges_check_in_both_source_orders() {
        let source = parsed(
            r#"interface EntityMetadata1 {
    get tableName(): string;
    set tableName(name: string);
}
interface EntityMetadata1 {
    tableName: string;
}

interface EntityMetadata2 {
    tableName: string;
}
interface EntityMetadata2 {
    get tableName(): string;
    set tableName(name: string);
}

class Foo1 {
    accessor x: string = "abc"
}
interface Foo1 {
    x: string
}

interface Foo2 {
    x: string
}
class Foo2 {
    accessor x: string = "abc"
}"#,
        );
        let file = FileId::new(8_684);
        let mut context = context(&[(file, &source)], CanonicalCheckerOptions::default());

        context.check_source_file(file).unwrap();

        let string = context.store().intrinsic_bootstrap().unwrap().string_type;
        for name in ["EntityMetadata1", "EntityMetadata2"] {
            let owner = global_symbol(&context, name);
            let property = context
                .store()
                .symbol(owner)
                .and_then(ts_binder::semantic::Symbol::members)
                .and_then(|members| context.store().symbol_table(members))
                .and_then(|members| members.get_source("tableName"))
                .unwrap();
            assert_eq!(
                context.store().symbol(property).unwrap().flags(),
                SymbolFlags::PROPERTY | SymbolFlags::GET_ACCESSOR | SymbolFlags::SET_ACCESSOR,
            );
            assert_eq!(
                context.store().value_symbol_links(property),
                Some(&ValueSymbolLinks {
                    resolved_type: Some(string),
                    ..ValueSymbolLinks::default()
                }),
            );
            assert!(
                context
                    .store()
                    .declared_type_links(owner)
                    .and_then(|links| links.declared_type)
                    .is_some()
            );
        }
        let regular = context
            .store()
            .intrinsic_bootstrap()
            .unwrap()
            .cached_string_literal_type("abc")
            .unwrap();
        let fresh = context.store().fresh_type_of_literal_type(regular).unwrap();
        for (name, class_first) in [("Foo1", true), ("Foo2", false)] {
            let owner = global_symbol(&context, name);
            let owner_record = context.store().symbol(owner).unwrap();
            assert_eq!(
                owner_record.flags(),
                SymbolFlags::CLASS | SymbolFlags::INTERFACE,
            );
            let [first, second] = owner_record.declarations().unwrap() else {
                panic!("{name} retains one class and one interface declaration")
            };
            let (class, interface) = if class_first {
                (*first, *second)
            } else {
                (*second, *first)
            };
            assert_eq!(owner_record.value_declaration(), Some(class));
            let NodeData::ClassDeclaration(class_data) =
                &source.arena.get(class.node).unwrap().data
            else {
                panic!("{name} retains its class declaration")
            };
            let NodeData::InterfaceDeclaration(interface_data) =
                &source.arena.get(interface.node).unwrap().data
            else {
                panic!("{name} retains its interface declaration")
            };
            let class_property = NodeRef::new(source.arena.id(), file, class_data.members.nodes[0]);
            let interface_property =
                NodeRef::new(source.arena.id(), file, interface_data.members.nodes[0]);
            let (_, bound) = context.file(file).unwrap();
            let property = bound.symbol(class_property).unwrap();
            assert_eq!(bound.symbol(interface_property), Some(property));
            let expected_declarations = if class_first {
                [class_property, interface_property]
            } else {
                [interface_property, class_property]
            };
            let property_record = context.store().symbol(property).unwrap();
            assert_eq!(
                property_record.flags(),
                SymbolFlags::PROPERTY | SymbolFlags::ACCESSOR,
            );
            assert_eq!(
                property_record.declarations(),
                Some(expected_declarations.as_slice()),
            );
            assert_eq!(
                property_record.value_declaration(),
                expected_declarations.first().copied(),
            );
            assert_eq!(
                context.store().value_symbol_links(property),
                Some(&ValueSymbolLinks {
                    resolved_type: Some(string),
                    ..ValueSymbolLinks::default()
                }),
            );
            let NodeData::PropertyDeclaration(class_property_data) =
                &source.arena.get(class_property.node).unwrap().data
            else {
                panic!("{name} retains its auto-accessor property")
            };
            let NodeData::PropertyDeclaration(interface_property_data) =
                &source.arena.get(interface_property.node).unwrap().data
            else {
                panic!("{name} retains its interface property")
            };
            for annotation in [
                NodeRef::new(source.arena.id(), file, class_property_data.type_.unwrap()),
                NodeRef::new(
                    source.arena.id(),
                    file,
                    interface_property_data.type_.unwrap(),
                ),
            ] {
                assert_eq!(
                    context.store().type_node_links(annotation),
                    Some(&TypeNodeLinks {
                        resolved_type: Some(string),
                        ..TypeNodeLinks::default()
                    }),
                );
            }
            let initializer = NodeRef::new(
                source.arena.id(),
                file,
                class_property_data.initializer.unwrap(),
            );
            assert_eq!(
                context.store().type_node_links(initializer),
                Some(&TypeNodeLinks {
                    resolved_type: Some(fresh),
                    ..TypeNodeLinks::default()
                }),
            );
            let instance = context
                .store()
                .declared_type_links(owner)
                .and_then(|links| links.declared_type)
                .unwrap();
            assert_eq!(
                validate_class_heritage_members(context.store(), instance),
                ClassHeritageMembersValidation::Valid,
            );
        }
        assert!(context.diagnostics().is_empty());
        assert!(is_type_checked(&context, file));

        let warm = observable_state(&context, file);
        context.recheck_source_file(file).unwrap();
        assert_eq!(observable_state(&context, file), warm);
    }

    #[test]
    fn reopened_interface_heritage_keeps_accessors_and_inherited_keys_in_source_order() {
        let source = parsed(concat!(
            "interface Base { get inherited(): string; set inherited(next: string); } ",
            "interface Base { inherited: string; } ",
            "interface Entry { get value(): string; set value(next: string); } ",
            "interface Entry extends Base { value: string; own: number; } ",
            "type Keys = keyof Entry;",
        ));
        let file = FileId::new(8_685);
        let mut context = context(&[(file, &source)], CanonicalCheckerOptions::default());

        context.check_source_file(file).unwrap();

        let base = global_symbol(&context, "Base");
        let entry = global_symbol(&context, "Entry");
        let entry_type = context
            .store()
            .declared_type_links(entry)
            .and_then(|links| links.declared_type)
            .unwrap();
        let properties = context
            .store()
            .type_payload(entry_type)
            .and_then(|record| record.data().structured())
            .and_then(|structured| structured.properties.as_deref())
            .unwrap();
        assert_eq!(
            properties
                .iter()
                .map(|property| context.store().symbol(*property).unwrap().name().as_utf8())
                .collect::<Vec<_>>(),
            [Some("value"), Some("own"), Some("inherited")],
        );
        assert_eq!(
            context.store().symbol(properties[0]).unwrap().flags(),
            SymbolFlags::PROPERTY | SymbolFlags::GET_ACCESSOR | SymbolFlags::SET_ACCESSOR,
        );
        assert_eq!(
            context.store().get_parent_of_symbol(properties[2]),
            Some(base)
        );
        assert_eq!(
            context.store().symbol(properties[2]).unwrap().flags(),
            SymbolFlags::PROPERTY | SymbolFlags::GET_ACCESSOR | SymbolFlags::SET_ACCESSOR,
        );

        let keys = global_symbol(&context, "Keys");
        let keys = context
            .store()
            .type_alias_links(keys)
            .and_then(|links| links.declared_type)
            .unwrap();
        let TypeData::Union(union) = context.store().type_payload(keys).unwrap().data() else {
            panic!("the accessor and inherited properties must produce three literal keys")
        };
        let mut names = union
            .union
            .types
            .iter()
            .map(
                |key| match context.store().type_payload(*key).unwrap().data() {
                    TypeData::Literal(literal) => match &literal.value {
                        LiteralValue::String(value) => value.as_str(),
                        _ => panic!("interface property keys must remain string literals"),
                    },
                    _ => panic!("interface property keys must remain string literals"),
                },
            )
            .collect::<Vec<_>>();
        names.sort_unstable();
        assert_eq!(names, ["inherited", "own", "value"]);
        assert!(context.diagnostics().is_empty());

        let warm = observable_state(&context, file);
        context.recheck_source_file(file).unwrap();
        assert_eq!(observable_state(&context, file), warm);
    }

    #[test]
    fn generic_source_heritage_preserves_inherited_indexes_and_explicit_members() {
        let source = parsed(concat!(
            "interface Dictionary<Value> { [key: string]: Value; } ",
            "interface Entry<Value> extends Dictionary<Value> { own: Value; }",
        ));
        let file = FileId::new(8_686);
        let mut context = context(&[(file, &source)], CanonicalCheckerOptions::default());

        context.check_source_file(file).unwrap();

        let dictionary = global_symbol(&context, "Dictionary");
        let entry = global_symbol(&context, "Entry");
        let target = context
            .store()
            .declared_type_links(entry)
            .and_then(|links| links.declared_type)
            .unwrap();
        let TypeData::Interface(interface) = context.store().type_payload(target).unwrap().data()
        else {
            panic!("the generic declaration must retain its interface target")
        };
        let [base] = interface.resolved_base_types.as_deref().unwrap() else {
            panic!("the derived generic declaration must retain its instantiated base")
        };
        assert_eq!(
            context.store().type_payload(*base).unwrap().symbol(),
            Some(dictionary)
        );

        let parameter = interface
            .reference
            .resolved_type_arguments
            .as_deref()
            .unwrap()[0];
        let members = context
            .store_mut_for_test()
            .resolve_generic_interface_members(target, None)
            .unwrap();
        assert_eq!(members.properties().len(), 1);
        assert_eq!(
            context
                .store()
                .symbol(members.properties()[0])
                .unwrap()
                .name()
                .as_utf8(),
            Some("own"),
        );
        let indexes = context
            .store()
            .type_payload(target)
            .and_then(|record| record.data().structured())
            .and_then(|structured| structured.index_infos.as_deref())
            .unwrap();
        let [index] = indexes else {
            panic!("the derived target must retain one inherited string index")
        };
        assert_eq!(
            context.store().index_info(*index).unwrap().value_type(),
            parameter
        );

        let number = context.store().intrinsic_bootstrap().unwrap().number_type;
        let reference = context
            .store_mut_for_test()
            .create_direct_generic_reference_type(target, &[number])
            .unwrap();
        context
            .store_mut_for_test()
            .resolve_generic_interface_members(reference, None)
            .unwrap();
        let [index] = context
            .store()
            .type_payload(reference)
            .and_then(|record| record.data().structured())
            .and_then(|structured| structured.index_infos.as_deref())
            .unwrap()
        else {
            panic!("the concrete reference must retain one inherited string index")
        };
        assert_eq!(
            context.store().index_info(*index).unwrap().value_type(),
            number
        );
        assert!(context.diagnostics().is_empty());

        let warm = observable_state(&context, file);
        context.recheck_source_file(file).unwrap();
        assert_eq!(observable_state(&context, file), warm);
    }

