    #[test]
    fn unresolved_import_equals_ambient_type_members_recover_without_alias_links() {
        let source = parsed(concat!(
            "import a1 = require('garbage'); ",
            "export declare var a: { ",
            "test1: a1.connectModule; ",
            "(): a1.connectExport; ",
            "};",
        ));
        let file = FileId::new(8_366);
        let declaration = source
            .arena
            .iter()
            .find_map(|(node, record)| {
                (record.kind == SyntaxKind::ImportEqualsDeclaration).then_some(NodeRef::new(
                    source.arena.id(),
                    file,
                    node,
                ))
            })
            .unwrap();
        let NodeData::ImportEqualsDeclaration(import) =
            &source.arena.get(declaration.node).unwrap().data
        else {
            panic!("expected one import-equals declaration")
        };
        let NodeData::ExternalModuleReference(external) =
            &source.arena.get(import.module_reference).unwrap().data
        else {
            panic!("expected one external require reference")
        };
        let specifier = NodeRef::new(source.arena.id(), file, external.expression);
        let mut context = CanonicalCheckerContext::new_with_module_resolutions(
            completed_bindings_with_module_state(
                &[(file, &source)],
                CanonicalModuleState::External,
            ),
            vec![(file, &source.arena)],
            CanonicalCheckerOptions::default(),
            CanonicalModuleResolutionManifestInput::new([
                CanonicalModuleResolutionEntry::unresolved(specifier),
            ]),
        )
        .unwrap();
        let (_, bound) = context.file(file).unwrap();
        let alias = bound.symbol(declaration).unwrap();
        let root = variable_type_node(&source, file, "a");

        context.check_source_file(file).unwrap();

        let error_type = context.store().intrinsic_bootstrap().unwrap().error_type;
        assert_eq!(
            variable_value_type(&context, &source, file, "a"),
            error_type
        );
        assert_eq!(resolved_node_type(&context, root), error_type);
        assert!(context.store().alias_symbol_links(alias).is_none());
        assert!(context.store().value_symbol_links(alias).is_none());
        assert!(context.diagnostics().is_empty());

        let warm = observable_state(&context, file);
        context.recheck_source_file(file).unwrap();
        assert_eq!(observable_state(&context, file), warm);
    }

    #[test]
    fn reserved_commonjs_import_equals_names_follow_emission_and_runtime_rules() {
        let cases = [
            (
                "import require = require('./target');",
                true,
                false,
                false,
                Some("require"),
            ),
            (
                "import exports = require('./target');",
                true,
                false,
                false,
                Some("exports"),
            ),
            (
                "import ordinary = require('./target');",
                true,
                false,
                false,
                None,
            ),
            (
                "import require = require('./target');",
                false,
                false,
                false,
                None,
            ),
            (
                "import require = require('./target');",
                true,
                true,
                false,
                None,
            ),
            (
                "import require = require('./target');",
                true,
                false,
                true,
                None,
            ),
            (
                "import type require = require('./target');",
                true,
                false,
                false,
                None,
            ),
        ];

        for (index, (text, emit_common_js, no_emit, declaration_file, expected)) in
            cases.into_iter().enumerate()
        {
            let source = parsed(text);
            let file = FileId::new(8_320 + u32::try_from(index).unwrap());
            let options = CanonicalCheckerOptions {
                emit_common_js,
                no_emit,
                ..CanonicalCheckerOptions::default()
            };
            let context = context_with_declaration_facts(
                file,
                &source,
                CanonicalModuleState::External,
                declaration_file,
                options,
            );
            let (_, bound) = context.file(file).unwrap();
            let declaration =
                source
                    .arena
                    .iter()
                    .find_map(|(node, record)| {
                        (record.kind == SyntaxKind::ImportEqualsDeclaration)
                            .then_some(NodeRef::new(source.arena.id(), file, node))
                    })
                    .unwrap();
            let plan =
                plan_top_level_import_equals(&source.arena, bound, context.store(), declaration)
                    .unwrap();
            let [binding] = plan.bindings.as_slice() else {
                panic!("expected exactly one import-equals alias")
            };
            let diagnostic =
                reserved_commonjs_import_equals_diagnostic(&source.arena, bound, options, binding)
                    .unwrap();

            match (expected, diagnostic) {
                (Some(name), Some(diagnostic)) => {
                    assert_eq!(diagnostic.diagnostic.code(), 2441);
                    assert_eq!(node_text(&source, diagnostic.node.unwrap()), name);
                    assert_eq!(
                        diagnostic.diagnostic.render().unwrap(),
                        format!(
                            "Duplicate identifier '{name}'. Compiler reserves name '{name}' in top level scope of a module."
                        ),
                    );
                }
                (None, None) => {}
                (expected, actual) => panic!(
                    "reserved-name mismatch for {text:?}: expected {expected:?}, got {actual:?}"
                ),
            }
        }
    }

