    #[test]
    fn javascript_comment_only_typedef_imports_use_promoted_commonjs_type_exports() {
        for (index, (exported_value, imported_type, variable)) in [
            ("0", "{ a: 1, m: 1 }", "var c;"),
            ("{}", "{ a: 1, m: 1 }", "var c;"),
            ("function () {}", "{ a: 1, m: 1 }", "var c;"),
            ("0", "number", "var c = 1;"),
            ("{}", "number", "var c = 1;"),
            ("function () {}", "number", "var c = 1;"),
        ]
        .into_iter()
        .enumerate()
        {
            let target = parse_javascript_source_file(&format!(
                "/** @typedef {{{imported_type}}} C */\nconst value = {exported_value};\nmodule.exports = value;",
            ));
            let imported = parse_javascript_source_file(&format!(
                "/** @typedef {{import('./target').C}} C */\n/** @type {{C}} */\n{variable}",
            ));
            assert!(target.diagnostics.is_empty(), "{:?}", target.diagnostics);
            assert!(
                imported.diagnostics.is_empty(),
                "{:?}",
                imported.diagnostics
            );
            let file_index = 8_370 + u32::try_from(index).unwrap() * 2;
            let target_file = FileId::new(file_index);
            let imported_file = FileId::new(file_index + 1);
            let files = [
                (target_file, &target, CanonicalModuleState::CommonJs),
                (imported_file, &imported, CanonicalModuleState::Script),
            ];

            let mut binder = CanonicalBinder::new();
            for (file, source, state) in files {
                binder
                    .bind_source_file_with_facts(
                        &source.arena,
                        source.source_file,
                        file,
                        CanonicalSourceFileFacts::new(
                            EscapedName::source(format!("\"/project/{}.js\"", file.index())),
                            CanonicalSourceLanguage::JavaScript,
                            false,
                            state,
                        ),
                    )
                    .unwrap();
            }
            for (file, source, _) in files {
                binder
                    .bind_javascript_declaration_slice(&source.arena, file)
                    .unwrap();
            }
            let (import_type, module_specifier, imported_name) = imported
                .arena
                .iter()
                .find_map(|(node, record)| {
                    let NodeData::ImportTypeNode(import) = &record.data else {
                        return None;
                    };
                    let NodeData::LiteralTypeNode(argument) =
                        &imported.arena.get(import.argument)?.data
                    else {
                        return None;
                    };
                    Some((node, argument.literal, import.qualifier?))
                })
                .expect("the source-owned JSDoc typedef retains its exact import nodes");
            let specifier = NodeRef::new(imported.arena.id(), imported_file, module_specifier);
            let manifest = CanonicalModuleResolutionManifestInput::new([
                CanonicalModuleResolutionEntry::resolved(
                    specifier,
                    CanonicalResolvedModuleInput::new(
                        target_file,
                        CanonicalModuleResolutionMode::Esm,
                        CanonicalModuleResolutionMode::CommonJs,
                    ),
                ),
            ]);
            let mut context = CanonicalCheckerContext::new_with_module_resolutions(
                binder.finish(),
                vec![
                    (target_file, &target.arena),
                    (imported_file, &imported.arena),
                ],
                CanonicalCheckerOptions::default(),
                manifest,
            )
            .unwrap();

            context.check_source_file(imported_file).unwrap();

            let (_, target_bound) = context.file(target_file).unwrap();
            let module = target_bound.symbol(target_bound.source_file()).unwrap();
            let target_symbol = context
                .store()
                .symbol(module)
                .and_then(ts_binder::semantic::Symbol::exports)
                .and_then(|exports| context.store().symbol_table(exports))
                .and_then(|exports| exports.get_source("C"))
                .unwrap();
            let target_type = context
                .store()
                .type_alias_links(target_symbol)
                .and_then(|links| links.declared_type)
                .unwrap();
            let imported_alias = imported
                .arena
                .iter()
                .find_map(|(node, record)| {
                    (record.kind == SyntaxKind::JsTypeAliasDeclaration).then_some(NodeRef::new(
                        imported.arena.id(),
                        imported_file,
                        node,
                    ))
                })
                .unwrap();
            let (_, imported_bound) = context.file(imported_file).unwrap();
            let local_symbol = imported_bound.symbol(imported_alias).unwrap();
            assert!(context.diagnostics().is_empty());
            assert_eq!(
                variable_value_type(&context, &imported, imported_file, "c"),
                target_type,
            );
            assert_eq!(
                context
                    .store()
                    .type_alias_links(local_symbol)
                    .and_then(|links| links.declared_type),
                Some(target_type),
            );
            assert_eq!(
                context
                    .store()
                    .type_node_links(NodeRef::new(
                        imported.arena.id(),
                        imported_file,
                        import_type,
                    ))
                    .and_then(|links| links.resolved_type),
                Some(target_type),
            );
            assert_eq!(
                context
                    .store()
                    .symbol_node_links(NodeRef::new(
                        imported.arena.id(),
                        imported_file,
                        imported_name,
                    ))
                    .and_then(|links| links.resolved_symbol),
                Some(target_symbol),
            );
            assert!(context.store().alias_symbol_links(local_symbol).is_none());

            let warm = observable_state(&context, imported_file);
            context.recheck_source_file(imported_file).unwrap();
            assert_eq!(observable_state(&context, imported_file), warm);
        }
    }

    #[test]
    fn javascript_imported_namespaced_jsdoc_typedefs_use_authenticated_static_imports() {
        let exported = parse_javascript_source_file(concat!(
            "/** @typedef {number} M.T */\n",
            "/** @type {M.T} */\n",
            "export const xd = 1;",
        ));
        let imported = parse_javascript_source_file(concat!(
            "import { xd } from './exported.js';\n",
            "/** @type {import('./exported.js').M.T} */\n",
            "export const ed = xd;",
        ));
        assert!(
            exported.diagnostics.is_empty(),
            "{:?}",
            exported.diagnostics
        );
        assert!(
            imported.diagnostics.is_empty(),
            "{:?}",
            imported.diagnostics
        );
        let exported_file = FileId::new(8_349);
        let imported_file = FileId::new(8_350);
        let files = [(exported_file, &exported), (imported_file, &imported)];

        let mut binder = CanonicalBinder::new();
        for (file, source) in files {
            binder
                .bind_source_file_with_facts(
                    &source.arena,
                    source.source_file,
                    file,
                    CanonicalSourceFileFacts::new(
                        EscapedName::source(format!("\"/project/{}.js\"", file.index())),
                        CanonicalSourceLanguage::JavaScript,
                        false,
                        CanonicalModuleState::External,
                    ),
                )
                .unwrap();
        }
        for (file, source) in files {
            binder
                .bind_javascript_declaration_slice(&source.arena, file)
                .unwrap();
        }
        let specifiers = source_module_specifiers(&imported);
        let [specifier] = specifiers.as_slice() else {
            panic!("the importing source must retain one authenticated module specifier")
        };
        let manifest = CanonicalModuleResolutionManifestInput::new([
            CanonicalModuleResolutionEntry::resolved(
                NodeRef::new(imported.arena.id(), imported_file, *specifier),
                CanonicalResolvedModuleInput::new(
                    exported_file,
                    CanonicalModuleResolutionMode::Esm,
                    CanonicalModuleResolutionMode::Esm,
                ),
            ),
        ]);
        let mut context = CanonicalCheckerContext::new_with_module_resolutions(
            binder.finish(),
            vec![
                (exported_file, &exported.arena),
                (imported_file, &imported.arena),
            ],
            CanonicalCheckerOptions::default(),
            manifest,
        )
        .unwrap();

        context.check_source_file(exported_file).unwrap();
        context.check_source_file(imported_file).unwrap();

        assert!(context.diagnostics().is_empty());
        assert_eq!(
            variable_value_type(&context, &imported, imported_file, "ed"),
            context.store().intrinsic_bootstrap().unwrap().number_type,
        );
        let warm = observable_state(&context, imported_file);
        context.recheck_source_file(imported_file).unwrap();
        assert_eq!(observable_state(&context, imported_file), warm);
    }

    #[test]
    fn nameless_jsdoc_callable_parameter_reports_exact_argument_diagnostic_and_replays_warm() {
        let source = parse_javascript_source_file(concat!(
            "/**\n",
            " * @param {(x: string) => string}\n",
            " */\n",
            "function foo(f) {\n",
            "    return f(123);\n",
            "}\n",
        ));
        assert!(source.diagnostics.is_empty(), "{:?}", source.diagnostics);
        let file = FileId::new(8_960);
        let mut context = javascript_context(
            file,
            &source,
            CanonicalCheckerOptions {
                no_implicit_any: true,
                ..CanonicalCheckerOptions::default()
            },
        );

        context.check_source_file(file).unwrap();

        let [diagnostic] = context.diagnostics().as_slice() else {
            panic!("expected exactly one typed JSDoc callback argument diagnostic")
        };
        assert_eq!(diagnostic.diagnostic.code(), 2345);
        assert_eq!(
            diagnostic.diagnostic.render().unwrap(),
            "Argument of type 'number' is not assignable to parameter of type 'string'.",
        );
        assert_eq!(node_text(&source, diagnostic.node.unwrap()), "123");

        let declaration = function_declaration(&source, file, "foo");
        let NodeData::FunctionDeclaration(function) =
            &source.arena.get(declaration.node).unwrap().data
        else {
            panic!("expected the annotated source function")
        };
        let [parameter] = function.parameters.nodes.as_slice() else {
            panic!("expected one source-owned callback parameter")
        };
        let parameter = NodeRef::new(source.arena.id(), file, *parameter);
        let (_, bound) = context.file(file).unwrap();
        let owner = bound.symbol(parameter).unwrap();
        let callback = context
            .store()
            .value_symbol_links(owner)
            .and_then(|links| links.resolved_type)
            .unwrap();
        assert_eq!(resolved_node_type(&context, parameter), callback);
        assert_eq!(
            context.type_to_string(callback).unwrap(),
            "(x: string) => string"
        );

        let signature = context
            .store()
            .signature_links(parameter)
            .and_then(|links| links.resolved_signature.signature())
            .unwrap();
        let record = context.store().signature(signature).unwrap();
        let string = context.store().intrinsic_bootstrap().unwrap().string_type;
        assert_eq!(record.declaration(), Some(parameter));
        assert_eq!(record.resolved_return_type(), Some(string));
        assert_eq!(
            context
                .store()
                .callable_signature_parameter_types(signature),
            Some([string].as_slice()),
        );
        let [argument] = record.parameters() else {
            panic!("expected one checker-owned callback argument")
        };
        assert_eq!(
            context.store().symbol(*argument).unwrap().name().as_utf8(),
            Some("x"),
        );

        let call = source
            .arena
            .iter()
            .find_map(|(node, record)| {
                (record.kind == SyntaxKind::CallExpression).then_some(NodeRef::new(
                    source.arena.id(),
                    file,
                    node,
                ))
            })
            .unwrap();
        assert_eq!(
            context
                .store()
                .signature_links(call)
                .and_then(|links| links.resolved_signature.signature()),
            Some(signature),
        );

        let warm = observable_state(&context, file);
        context.recheck_source_file(file).unwrap();
        assert_eq!(observable_state(&context, file), warm);
    }

    #[test]
    fn duplicate_javascript_functions_share_the_first_signature_and_check_later_parameters() {
        let source = parse_javascript_source_file("function f() {} function f(value) {}");
        assert!(source.diagnostics.is_empty(), "{:?}", source.diagnostics);
        let file = FileId::new(8_351);
        let mut context = javascript_context(
            file,
            &source,
            CanonicalCheckerOptions {
                no_implicit_any: true,
                ..CanonicalCheckerOptions::default()
            },
        );

        context.check_source_file(file).unwrap();

        let [diagnostic] = context.diagnostics().as_slice() else {
            panic!("expected one implicit-any diagnostic on the second implementation")
        };
        assert_eq!(diagnostic.diagnostic.code(), 7006);
        assert_eq!(node_text(&source, diagnostic.node.unwrap()), "value");

        let first = function_declaration(&source, file, "f");
        let (_, bound) = context.file(file).unwrap();
        let owner = bound.symbol(first).unwrap();
        let callable = context
            .store()
            .source_callable_type_for_owner(owner)
            .unwrap();
        let signature = context
            .store()
            .source_callable_provenance(callable)
            .map(|provenance| provenance.signature)
            .unwrap();
        assert!(
            context
                .store()
                .signature(signature)
                .unwrap()
                .parameters()
                .is_empty()
        );
        let parameter = source
            .arena
            .iter()
            .find_map(|(node, record)| {
                (record.kind == SyntaxKind::Parameter).then_some(NodeRef::new(
                    source.arena.id(),
                    file,
                    node,
                ))
            })
            .unwrap();
        let parameter_symbol = bound.symbol(parameter).unwrap();
        assert_eq!(
            context
                .store()
                .value_symbol_links(parameter_symbol)
                .and_then(|links| links.resolved_type),
            Some(context.store().intrinsic_bootstrap().unwrap().any_type),
        );

        let warm = observable_state(&context, file);
        context.recheck_source_file(file).unwrap();
        assert_eq!(observable_state(&context, file), warm);
    }

    #[test]
    fn noncontiguous_javascript_duplicate_functions_preserve_owner_and_parameter_diagnostics() {
        let source = parse_javascript_source_file(concat!(
            "function repeated(first) {} ",
            "const marker = 1; ",
            "function repeated(second, third) {} ",
            "function repeated(last) {}",
        ));
        assert!(source.diagnostics.is_empty(), "{:?}", source.diagnostics);

        for (index, no_implicit_any) in [false, true].into_iter().enumerate() {
            let file = FileId::new(8_360 + u32::try_from(index).unwrap());
            let mut context = javascript_context(
                file,
                &source,
                CanonicalCheckerOptions {
                    no_implicit_any,
                    ..CanonicalCheckerOptions::default()
                },
            );

            context.check_source_file(file).unwrap();

            let expected: &[&str] = if no_implicit_any {
                &["first", "second", "third", "last"]
            } else {
                &[]
            };
            assert_eq!(
                context
                    .diagnostics()
                    .as_slice()
                    .iter()
                    .map(|diagnostic| {
                        assert_eq!(diagnostic.diagnostic.code(), 7006);
                        node_text(&source, diagnostic.node.unwrap())
                    })
                    .collect::<Vec<_>>(),
                expected,
            );

            let first = function_declaration(&source, file, "repeated");
            let (_, bound) = context.file(file).unwrap();
            let owner = bound.symbol(first).unwrap();
            let declarations = context
                .store()
                .symbol(owner)
                .unwrap()
                .declarations()
                .unwrap();
            assert_eq!(declarations.len(), 3);
            assert_eq!(declarations[0], first);
            assert!(declarations[1..].iter().all(|declaration| {
                bound.symbol(*declaration) == Some(owner)
                    && context
                        .store()
                        .source_callable_type_for_declaration(*declaration)
                        .is_none()
            }));

            let callable = context
                .store()
                .source_callable_type_for_owner(owner)
                .unwrap();
            let signature = context
                .store()
                .source_callable_provenance(callable)
                .map(|provenance| provenance.signature)
                .unwrap();
            assert_eq!(
                context
                    .store()
                    .signature(signature)
                    .unwrap()
                    .parameters()
                    .len(),
                1,
            );

            let warm = observable_state(&context, file);
            context.recheck_source_file(file).unwrap();
            assert_eq!(observable_state(&context, file), warm);
        }
    }

