    #[test]
    fn nested_commonjs_named_exports_preserve_export_types_and_warm_caches() {
        let source = parse_javascript_source_file(concat!(
            "module.exports.value = 1; ",
            "exports.value = 2; ",
            "module.exports.ready = true;",
        ));
        assert!(source.diagnostics.is_empty(), "{:?}", source.diagnostics);
        let file = FileId::new(8_398);
        let mut context = javascript_context(file, &source, CanonicalCheckerOptions::default());

        context.check_source_file(file).unwrap();

        let (_, bound) = context.file(file).unwrap();
        let module = bound.symbol(bound.source_file()).unwrap();
        let exports = context
            .store()
            .symbol(module)
            .and_then(ts_binder::semantic::Symbol::exports)
            .and_then(|exports| context.store().symbol_table(exports))
            .unwrap();
        let value = exports.get_source("value").unwrap();
        let value_type = context
            .store()
            .value_symbol_links(value)
            .and_then(|links| links.resolved_type)
            .unwrap();
        let TypeData::Union(union) = context.store().type_payload(value_type).unwrap().data()
        else {
            panic!("repeated CommonJS exports must retain their regular literal union")
        };
        assert_eq!(union.union.types.len(), 2);
        for index in 0..2 {
            let (_, right) = assignment_parts(&source, file, index);
            let TypeData::Literal(literal) = context
                .store()
                .type_payload(resolved_node_type(&context, right))
                .unwrap()
                .data()
            else {
                panic!("CommonJS export assignments must retain their source literal")
            };
            assert!(union.union.types.contains(&literal.regular_type));
        }
        let ready = exports.get_source("ready").unwrap();
        assert_eq!(
            context
                .store()
                .value_symbol_links(ready)
                .and_then(|links| links.resolved_type),
            Some(
                context
                    .store()
                    .intrinsic_bootstrap()
                    .unwrap()
                    .regular_true_type,
            ),
        );
        assert!(context.diagnostics().is_empty());

        let warm = observable_state(&context, file);
        context.recheck_source_file(file).unwrap();
        assert_eq!(observable_state(&context, file), warm);
    }

    #[test]
    fn computed_commonjs_named_exports_share_binder_owned_properties() {
        let source = parse_javascript_source_file(concat!(
            "exports['value'] = 1; ",
            "module.exports.value = 2; ",
            "module.exports['ready'] = true;",
        ));
        assert!(source.diagnostics.is_empty(), "{:?}", source.diagnostics);
        let file = FileId::new(8_400);
        let mut context = javascript_context(file, &source, CanonicalCheckerOptions::default());

        context.check_source_file(file).unwrap();

        let (_, bound) = context.file(file).unwrap();
        let module = bound.symbol(bound.source_file()).unwrap();
        let exports = context
            .store()
            .symbol(module)
            .and_then(ts_binder::semantic::Symbol::exports)
            .and_then(|exports| context.store().symbol_table(exports))
            .unwrap();
        let (computed, _) = assignment_parts(&source, file, 0);
        let NodeData::ElementAccessExpression(access) =
            &source.arena.get(computed.node).unwrap().data
        else {
            panic!("the first CommonJS export must retain its computed access")
        };
        let receiver = NodeRef::new(source.arena.id(), file, access.expression);
        let exports_alias = bound
            .locals(bound.source_file())
            .and_then(|locals| context.store().symbol_table(locals))
            .and_then(|locals| locals.get_source("exports"))
            .unwrap();
        assert_eq!(
            context.store().symbol(exports_alias).unwrap().flags(),
            SymbolFlags::FUNCTION_SCOPED_VARIABLE | SymbolFlags::MODULE_EXPORTS,
        );
        assert!(context.store().symbol_node_links(receiver).is_none());
        let value_type = context
            .store()
            .value_symbol_links(exports.get_source("value").unwrap())
            .and_then(|links| links.resolved_type)
            .unwrap();
        let TypeData::Union(union) = context.store().type_payload(value_type).unwrap().data()
        else {
            panic!("computed CommonJS exports must retain their regular literal union")
        };
        assert_eq!(union.union.types.len(), 2);
        for index in 0..2 {
            let (_, right) = assignment_parts(&source, file, index);
            let TypeData::Literal(literal) = context
                .store()
                .type_payload(resolved_node_type(&context, right))
                .unwrap()
                .data()
            else {
                panic!("computed CommonJS assignments must retain their source literal")
            };
            assert!(union.union.types.contains(&literal.regular_type));
        }
        assert_eq!(
            context
                .store()
                .value_symbol_links(exports.get_source("ready").unwrap())
                .and_then(|links| links.resolved_type),
            Some(
                context
                    .store()
                    .intrinsic_bootstrap()
                    .unwrap()
                    .regular_true_type,
            ),
        );
        assert!(context.diagnostics().is_empty());

        let warm = observable_state(&context, file);
        context.recheck_source_file(file).unwrap();
        assert_eq!(observable_state(&context, file), warm);
    }

    #[test]
    fn nested_commonjs_named_exports_preserve_imported_value_identity() {
        let target = parse_javascript_source_file("module.exports.value = 1;");
        let importer = parsed("import { value } from './target.js'; const copied = value;");
        assert!(target.diagnostics.is_empty(), "{:?}", target.diagnostics);
        let target_file = FileId::new(8_401);
        let importer_file = FileId::new(8_402);
        let mut binder = CanonicalBinder::new();
        binder
            .bind_source_file_with_facts(
                &target.arena,
                target.source_file,
                target_file,
                CanonicalSourceFileFacts::new(
                    EscapedName::source("\"/project/target.js\""),
                    CanonicalSourceLanguage::JavaScript,
                    false,
                    CanonicalModuleState::Script,
                ),
            )
            .unwrap();
        binder
            .bind_source_file_with_facts(
                &importer.arena,
                importer.source_file,
                importer_file,
                CanonicalSourceFileFacts::new(
                    EscapedName::source("\"/project/importer.ts\""),
                    CanonicalSourceLanguage::TypeScript,
                    false,
                    CanonicalModuleState::External,
                ),
            )
            .unwrap();
        binder
            .bind_javascript_declaration_slice(&target.arena, target_file)
            .unwrap();
        binder
            .bind_typescript_declaration_slice(&importer.arena, importer_file)
            .unwrap();
        let specifiers = source_module_specifiers(&importer);
        let [specifier] = specifiers.as_slice() else {
            panic!("expected one authenticated CommonJS module specifier")
        };
        let manifest = CanonicalModuleResolutionManifestInput::new([
            CanonicalModuleResolutionEntry::resolved(
                NodeRef::new(importer.arena.id(), importer_file, *specifier),
                CanonicalResolvedModuleInput::new(
                    target_file,
                    CanonicalModuleResolutionMode::Esm,
                    CanonicalModuleResolutionMode::CommonJs,
                ),
            ),
        ]);
        let mut context = CanonicalCheckerContext::new_with_module_resolutions(
            binder.finish(),
            vec![
                (target_file, &target.arena),
                (importer_file, &importer.arena),
            ],
            CanonicalCheckerOptions::default(),
            manifest,
        )
        .unwrap();

        context.check_source_file(target_file).unwrap();
        context.check_source_file(importer_file).unwrap();

        let (_, target_bound) = context.file(target_file).unwrap();
        let target_module = target_bound.symbol(target_bound.source_file()).unwrap();
        let exported = context
            .store()
            .symbol(target_module)
            .and_then(ts_binder::semantic::Symbol::exports)
            .and_then(|exports| context.store().symbol_table(exports))
            .and_then(|exports| exports.get_source("value"))
            .unwrap();
        let exported_type = context
            .store()
            .value_symbol_links(exported)
            .and_then(|links| links.resolved_type)
            .unwrap();
        assert_eq!(context.type_to_string(exported_type).unwrap(), "1");
        assert_eq!(
            variable_value_type(&context, &importer, importer_file, "copied"),
            exported_type,
        );
        assert!(context.diagnostics().is_empty());
        let warm = observable_state(&context, importer_file);
        context.recheck_source_file(target_file).unwrap();
        context.recheck_source_file(importer_file).unwrap();
        assert_eq!(observable_state(&context, importer_file), warm);
    }

