    #[test]
    fn primitive_binary_operator_kind_must_match_its_exact_source_spelling() {
        for (file, text) in [
            (FileId::new(409), "const value = 1 + 2;"),
            (FileId::new(410), "var target: number = 0; target = 1 + 2;"),
            (
                FileId::new(411),
                concat!(
                    "function take(value: number): number { return value; } ",
                    "const value = take(1 + 2);",
                ),
            ),
        ] {
            let mut source = parsed(text);
            let (binary_id, operator_id) = source
                .arena
                .iter()
                .find_map(|(node, record)| {
                    let NodeData::BinaryExpression(binary) = &record.data else {
                        return None;
                    };
                    (source.arena.get(binary.operator_token)?.kind == SyntaxKind::PlusToken)
                        .then_some((node, binary.operator_token))
                })
                .expect("fixture must contain a primitive plus expression");
            source.arena.get_mut(operator_id).unwrap().kind = SyntaxKind::MinusToken;
            let binary = NodeRef::new(source.arena.id(), file, binary_id);
            let operator = NodeRef::new(source.arena.id(), file, operator_id);
            let mut context = context(&[(file, &source)], CanonicalCheckerOptions::default());
            let before = observable_state(&context, file);

            assert_eq!(
                context.check_source_file(file),
                Err(SourceCheckError::PrimitiveOperator(operator)),
                "source: {text}",
            );

            assert_eq!(observable_state(&context, file), before, "source: {text}");
            assert!(context.store().type_node_links(binary).is_none());
            assert!(context.diagnostics().is_empty());
            assert!(!is_type_checked(&context, file));
        }
    }

    #[test]
    fn primitive_binary_root_cache_poison_retains_diagnostics_only_until_repair() {
        let source = parsed("const value = 1 + true;");
        let file = FileId::new(405);
        let mut context = context(&[(file, &source)], CanonicalCheckerOptions::default());
        let binary = variable_initializer(&source, file, "value");
        let (poison, expected) = {
            let bootstrap = context.store().intrinsic_bootstrap().unwrap();
            (bootstrap.number_type, bootstrap.any_type)
        };
        assert_ne!(poison, expected);
        assert!(context.store_mut_for_test().set_type_node_links(
            binary,
            TypeNodeLinks {
                resolved_type: Some(poison),
                ..TypeNodeLinks::default()
            },
        ));

        let error = SourceCheckError::Assertion(SourceAssertionError::InvalidExpressionCache {
            node: binary,
            cached: Some(poison),
            expected,
        });
        assert_eq!(context.check_source_file(file), Err(error));
        assert!(context.diagnostics().is_empty());
        assert!(!is_type_checked(&context, file));
        let rejected = observable_state(&context, file);
        assert_eq!(context.check_source_file(file), Err(error));
        assert_eq!(observable_state(&context, file), rejected);

        assert!(
            context
                .store_mut_for_test()
                .set_type_node_links(binary, TypeNodeLinks::default())
        );
        context.check_source_file(file).unwrap();
        let [diagnostic] = context.diagnostics().as_slice() else {
            panic!("expected the retained operator diagnostic")
        };
        assert_eq!(diagnostic.node, Some(binary));
        assert_eq!(diagnostic.diagnostic.code(), 2365);
        assert_eq!(diagnostic.diagnostic.arguments, ["+", "number", "boolean"]);
        assert_eq!(resolved_node_type(&context, binary), expected);
        assert!(is_type_checked(&context, file));
    }

    #[test]
    fn constant_boolean_conditionals_match_loose_upstream_types_and_replay_warm() {
        let library = parsed("interface Array<T> {} interface ReadonlyArray<T> {}");
        let source = parsed(concat!(
            "var a = false ? 1 : null; ",
            "var b = false ? undefined : 0; ",
            "var c = false ? 1 : 0; ",
            "var d = false ? false : true; ",
            "var e = false ? 'foo' : 'bar'; ",
            "var f = false ? null : undefined; ",
            "var g = true ? { g: 5 } : null; ",
            "var h = [{ h: 5 }, null]; ",
            "function i() { if (true) { return { x: 5 }; } else { return null; } }",
        ));
        let library_file = FileId::new(4_810);
        let source_file = FileId::new(4_811);
        let mut context = context_with_default_library_files(
            &[(library_file, &library), (source_file, &source)],
            &[library_file],
            CanonicalCheckerOptions {
                allow_unreachable_code: Some(true),
                ..CanonicalCheckerOptions::default()
            },
        );

        context.check_source_file(source_file).unwrap();

        for (name, expected) in [
            ("a", "number"),
            ("b", "number"),
            ("c", "number"),
            ("d", "boolean"),
            ("e", "string"),
            ("f", "any"),
            ("g", "{ g: number; }"),
            ("h", "{ h: number; }[]"),
        ] {
            let type_ = variable_value_type(&context, &source, source_file, name);
            assert_eq!(
                context.type_to_string(type_).unwrap(),
                expected,
                "variable {name}",
            );
        }

        let callable = context
            .store()
            .source_callable_type_for_owner(function_symbol(&context, &source, source_file, "i"))
            .unwrap();
        assert_eq!(
            context.type_to_string(callable).unwrap(),
            "() => { x: number; }"
        );
        assert!(
            context.diagnostics().is_empty(),
            "{:?}",
            context.diagnostics()
        );

        let warm = observable_state(&context, source_file);
        context.recheck_source_file(source_file).unwrap();
        assert_eq!(observable_state(&context, source_file), warm);
    }

    #[test]
    fn constant_boolean_conditionals_preserve_strict_nullable_branch_unions() {
        let source = parsed(concat!(
            "var numeric = false ? 1 : null; ",
            "var missing = true ? undefined : 0; ",
            "var truth = false ? false : true; ",
            "const fixed = false ? 1 : 0;",
        ));
        let file = FileId::new(4_812);
        let mut context = context(
            &[(file, &source)],
            CanonicalCheckerOptions {
                intrinsic: IntrinsicBootstrapOptions {
                    strict_null_checks: true,
                    exact_optional_property_types: false,
                },
                ..CanonicalCheckerOptions::default()
            },
        );

        context.check_source_file(file).unwrap();

        let bootstrap = context.store().intrinsic_bootstrap().unwrap();
        for (name, nullable) in [
            ("numeric", bootstrap.null_type),
            ("missing", bootstrap.undefined_type),
        ] {
            let type_ = variable_value_type(&context, &source, file, name);
            let Some(TypeData::Union(union)) =
                context.store().type_payload(type_).map(TypeRecord::data)
            else {
                panic!("{name} must retain its nullable branch union")
            };
            assert!(union.union.types.contains(&bootstrap.number_type));
            assert!(union.union.types.contains(&nullable));
        }
        assert_eq!(
            variable_value_type(&context, &source, file, "truth"),
            bootstrap.boolean_type,
        );
        assert_eq!(
            context
                .type_to_string(variable_value_type(&context, &source, file, "fixed"))
                .unwrap(),
            "0 | 1",
        );
        assert!(context.diagnostics().is_empty());
        let warm = observable_state(&context, file);
        context.recheck_source_file(file).unwrap();
        assert_eq!(observable_state(&context, file), warm);
    }

